style.css:
@-moz-document domain("facebook.com") {
/* ===== Colors ===== */
  :root, .__fb-light-mode, .__fb-dark-mode {
    --web-wash: transparent !important;
    --surface-background: rgba(20, 18, 50, 0.55) !important;
    --card-background: rgba(255, 255, 255, 0.07) !important;
    --comment-background: rgba(255, 255, 255, 0.10) !important;
    --primary-text: #f3f4ff !important;
    --secondary-text: #b9c0ee !important;
    --primary-icon: #f3f4ff !important;
    --secondary-icon: #b9c0ee !important;
    --accent: #8fd8ff !important;
    --primary-button-background: #6a7dff !important;
    --divider: rgba(255, 255, 255, 0.10) !important;
    --media-inner-border: transparent !important;
    --hover-overlay: rgba(255, 255, 255, 0.08) !important;
  }

  /* ===== Background ===== */
  html, body {
    background:
      radial-gradient(circle at 15% 10%, rgba(143, 216, 255, 0.18), transparent 40%),
      radial-gradient(circle at 85% 90%, rgba(196, 120, 255, 0.20), transparent 45%),
      linear-gradient(135deg, #141838 0%, #2b1760 50%, #0d4f6e 100%) fixed !important;
  }

  /* ===== Top bar ===== */
  [role="banner"] {
    background: rgba(24, 20, 60, 0.92) !important;
    backdrop-filter: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.12) !important;
    box-shadow: 0 4px 18px rgba(0, 0, 0, 0.35) !important;
    z-index: 9999 !important;
  }

  /* ===== Right sidebar: no big box ===== */
  [role="complementary"],
  [role="complementary"] > div {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* ===== Feed posts only ===== */
  [role="main"] [role="feed"] > div {
    margin-bottom: 14px !important;
  }
  [role="main"] [role="feed"] > div > div > div > div {
    border-radius: 18px !important;
  }
  [role="main"] [role="feed"] > div > div > div > div > div {
    background: linear-gradient(165deg, rgba(255,255,255,0.12) 0%, rgba(255,255,255,0.04) 55%) !important;
    border: 1px solid rgba(255, 255, 255, 0.14) !important;
    border-radius: 18px !important;
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.25),
      0 10px 30px rgba(0, 0, 0, 0.30) !important;
    overflow: hidden !important;
  }

  /* comments stay flat inside posts */
  [role="feed"] [role="article"] [role="article"] {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* ===== Left menu hover pill ===== */
  [role="navigation"] a[role="link"]:hover,
  [role="navigation"] div[role="button"]:hover {
    background: rgba(255, 255, 255, 0.10) !important;
    border-radius: 12px !important;
  }

  /* ===== Stories: rounded ===== */
  [aria-label*="tories"] a,
  [aria-label*="tories"] div[role="button"] {
    border-radius: 14px !important;
    overflow: hidden !important;
  }

  /* ===== Inputs ===== */
  input[type="search"],
  [role="main"] [contenteditable="true"] {
    background: rgba(255, 255, 255, 0.10) !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    border-radius: 20px !important;
  }

  /* ===== Chat window: no boxed messages ===== */
  [role="dialog"] [role="row"],
  [role="dialog"] [role="gridcell"] {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* ===== Scrollbar ===== */
  ::-webkit-scrollbar { width: 8px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #8fd8ff, #a06bff);
    border-radius: 10px;
  }
}
